  20|package com.puppycrawl.tools.checkstyle.utils;
  21|
  22|import java.io.IOException;
  23|import java.nio.file.Files;
  24|import java.nio.file.Path;
  25|
  26|/**
  27| * Class which provides OS related utilities.
  28| */
  29|public final class OsSpecificUtil {
  30|
  31|    /**
  32|     * Hiding public and default constructor.
  33|     */
  34|    private OsSpecificUtil() {
  35|
  36|    }
  37|
  38|    /**
  39|     * Updates the specified directory by resolving symbolic links, ensuring it exists,
  40|     * and creating any necessary parent directories. If the provided path is a symbolic
  41|     * link, it resolves it to the actual directory, throwing an IOException if the
  42|     * resolved path is not a directory. Creates directories if they do not exist.
  43|     *
  44|     * @param directory The path to the directory to be updated.
  45|     * @throws IOException If an I/O error occurs or if the resolved symbolic link is
  46|     *                     not a directory.
  47|     */
  48|    public static void updateDirectory(Path directory) throws IOException {
  49|        Path targetDirectory = directory;
  50|
  51|        if (Files.isSymbolicLink(directory)) {
  52|            final Path actualDir = directory.toRealPath();
  53|
  54|            if (Files.isDirectory(actualDir)) {
  55|                targetDirectory = actualDir;
  56|            }
  57|            else {
  58|                throw new IOException("Resolved symbolic link "
  59|                        + directory + " is not a directory.");
  60|            }
  61|        }
  62|        Files.createDirectories(targetDirectory);
  63|    }
  64|
